SELECT stocks_id                       AS stocksId,
       date_trunc('minute', reg_date_time) AS minuteTime
FROM torn_stocks_history
WHERE deleted = 0
  AND stocks_id IN

      #{id}

  AND reg_date_time >= #{start}
  AND reg_date_time < #{end}

SELECT stocks_id                                   AS stocksId,
       COUNT(DISTINCT date_trunc('minute', reg_date_time)) AS minuteCount
FROM torn_stocks_history
WHERE deleted = 0
  AND stocks_id IN

      #{id}

  AND reg_date_time >= #{start}
  AND reg_date_time < #{end}
GROUP BY stocks_id
